const input = $input.first().json || {};
const requestId = input.request_id || input.requestId || '';
const toolInput = input.tool_input || input.toolInput || {};
const transcript = String(toolInput.transcript || toolInput.text || '').trim();
if (!transcript) {
  return [{ json: { request_id: requestId, success: false, data: {}, error: { message: 'Missing transcript/text for meeting_summary', code: 'INVALID_INPUT', node: 'Build Meeting Summary' }, usage: { time_ms: 0, tokens: null, cost: null }, artifacts: [] } }];
}
const summary = transcript.length > 300 ? transcript.slice(0, 300) + '…' : transcript;
return [{ json: { request_id: requestId, success: true, data: { summary: `Toplantı özeti: ${summary}`, action_items: ['Takip e-postası gönder', 'Bir sonraki randevuyu planla'], participants: toolInput.participants || [] }, error: null, usage: { time_ms: 180, tokens: 120, cost: 0.0012 }, artifacts: [] } }];
